-- 1. create the database
CREATE DATABASE ReadExternalDataDB;
GO

-- 3. Create a Database Master Key (Required for Scoped Credentials)
CREATE MASTER KEY ENCRYPTION BY PASSWORD = 'YourStrongPassword123!';
GO

-- 4. Create Database Scoped Credential using Workspace Managed Identity
CREATE DATABASE SCOPED CREDENTIAL WorkspaceMSICredential
WITH IDENTITY = 'Managed Identity';
GO


CREATE EXTERNAL DATA SOURCE FintechDataExternal
WITH (
    LOCATION = 'https://fintechrawdata.dfs.core.windows.net/',
    CREDENTIAL = WorkspaceMSICredential
);
